import{_ as t,o as r,c as a,a5 as s}from"./chunks/framework.BmD0ICqc.js";const i="/study/images/hardware/pcie-links.svg",f=JSON.parse('{"title":"PCI Expressのリンクとレーン","description":"","frontmatter":{"title":"PCI Expressのリンクとレーン","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"hardware","summary":"CPU側からGPU・NVMe SSD・NICまでのPCIe経路をたどる。リンクの世代と幅、片方向帯域の計算、経路上のボトルネックを扱う。","aliases":["PCI Express","PCIe","root complex","root port","endpoint","switch","lane","レーン","リンク幅","GT/s"],"verification":"PCI-SIGの公開技術資料、MicrosoftのPCIeレジスター資料、LinuxカーネルのPCI API資料に照合（2026-11-07）"}},"headers":[],"relativePath":"hardware/io/pcie-links.md","filePath":"hardware/io/pcie-links.md"}'),n={name:"hardware/io/pcie-links.md"};function o(l,e,d,p,h,c){return r(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="pci-expressのリンクとレーン" tabindex="-1">PCI Expressのリンクとレーン <a class="header-anchor" href="#pci-expressのリンクとレーン" aria-label="Permalink to &quot;PCI Expressのリンクとレーン&quot;">​</a></h1><p>PCの各部品が担う役割は、<a href="/study/hardware/computer-components.html">コンピュータを構成する部品</a>の図で確認できます。</p><p>GPUへのアップロード、NVMe SSDからの読み取り、ネットワークカードでのパケット受信では、データがCPU・メモリ側とデバイスの間を移動します。<strong>PCI Express（PCIe）<strong>は、こうした機器を、両端にポートを持つ点対点の</strong>リンク</strong>で結びます。どのリンクを通り、各リンクが何レーン・何GT/sで動くかを調べると、転送経路のどこで帯域を使い合うかが分かります。<a href="https://www.intel.com/content/dam/support/us/en/programmable/support-resources/fpga-wiki/asset03/pci-express-base-r2.1.pdf#page=39" target="_blank" rel="noreferrer">Intel公開のPCIeトポロジー資料 §1.3</a></p><h2 id="cpu側からデバイスまでの経路" tabindex="-1">CPU側からデバイスまでの経路 <a class="header-anchor" href="#cpu側からデバイスまでの経路" aria-label="Permalink to &quot;CPU側からデバイスまでの経路&quot;">​</a></h2><p><strong>ルートコンプレックス（Root Complex）<strong>はCPU・メモリ側とPCIe階層をつなぎます。その</strong>ルートポート</strong>から、GPUなどの<strong>エンドポイント</strong>へ直接リンクを張ることも、PCIeスイッチへつなぐこともできます。スイッチは上流ポートと複数の下流ポートを持ち、行き先に応じてトランザクションを中継します。CPU側へ向かう複数機器のデータが同じ上流リンクを通る構成では、そのリンクの帯域を分け合います。<a href="https://www.intel.com/content/dam/support/us/en/programmable/support-resources/fpga-wiki/asset03/pci-express-base-r2.1.pdf#page=39" target="_blank" rel="noreferrer">Intel公開のPCIeトポロジー資料 §1.3</a> · <a href="https://docs.kernel.org/driver-api/pci/pci.html" target="_blank" rel="noreferrer">Linux PCIサポートライブラリー</a></p><figure class="study-figure"><img src="'+i+'" alt="CPUとRAMにつながるルートコンプレックスから、GPUへ直結するx16リンクとPCIeスイッチへ向かうx4リンクが伸びる。スイッチに接続したNVMe SSDとNICは、CPU側との通信で上流x4を共有する。" width="760" height="424" loading="lazy"><figcaption>GPUが直結し、SSDとNICがスイッチを経由する構成例です。各リンクの幅と経路上で共有する区間を見ます。<a href="/study/images/hardware/pcie-links.svg" target="_blank" rel="noopener noreferrer">PCIeの接続図を拡大</a></figcaption></figure><h2 id="レーン数と速度はリンクごとに決まる" tabindex="-1">レーン数と速度はリンクごとに決まる <a class="header-anchor" href="#レーン数と速度はリンクごとに決まる" aria-label="Permalink to &quot;レーン数と速度はリンクごとに決まる&quot;">​</a></h2><p>1レーンには送信用と受信用の差動ペアがあり、両方向へ同時に信号を送れます。複数のレーンをまとめて1リンクとして動かし、<code>x4</code>なら4レーン、<code>x16</code>なら16レーンです。リンクを立ち上げるトレーニングで、両端の能力と利用できるレーンに応じて速度・幅が決まります。ボードの仕様にあるスロットの長さ、電気的に配線されたレーン数、リンクが現在使うレーン数はそれぞれ確認します。例えばx16形状のスロットでも、配線がx4ならリンクに使えるのは最大4レーンです。<a href="https://pcisig.com/sites/default/files/files/PCI-SIG%20Cabling%20Webinar_FINAL.pdf" target="_blank" rel="noreferrer">PCI-SIGの公開リンク技術資料</a> · <a href="https://learn.microsoft.com/en-us/windows-hardware/drivers/ddi/ntddk/ns-ntddk-_pci_express_link_status_register" target="_blank" rel="noreferrer">Microsoftの交渉済みリンク速度と幅</a></p><p>調査では、機器が<strong>対応できる最大値</strong>と、実際に<strong>交渉された値</strong>を並べて見ます。例えばGen 5対応のSSDでも、接続先とGen 4 x4で交渉された場合は、そのリンクの計算に16 GT/sと4レーンを使います。スイッチや別のブリッジがあれば上流リンクの設定も確認します。<a href="https://learn.microsoft.com/en-us/windows-hardware/drivers/ddi/ntddk/ns-ntddk-pci_express_link_capabilities_2_register" target="_blank" rel="noreferrer">Microsoftの対応速度レジスター</a> · <a href="https://docs.kernel.org/driver-api/pci/pci.html#c.pcie_bandwidth_available" target="_blank" rel="noreferrer">Linuxの経路上のリンク帯域確認</a></p><h2 id="gt-sから片方向のバイト数を見積もる" tabindex="-1">GT/sから片方向のバイト数を見積もる <a class="header-anchor" href="#gt-sから片方向のバイト数を見積もる" aria-label="Permalink to &quot;GT/sから片方向のバイト数を見積もる&quot;">​</a></h2><p>GT/sは、1レーンが1秒間に行う転送回数を10億回単位で表します。Gen 3〜5のNRZでは1転送が1ビットに対応し、128b/130bの符号化で128ビットごとに130ビットを使います。ここでの片方向の計算値は、<code>GT/s × (128 / 130) ÷ 8 × レーン数</code> GB/sです。例えばGen 4 x4なら <code>16 × 128 / 130 ÷ 8 × 4 ≈ 7.88</code> GB/s です。1 GBは10億バイトとして計算します。<a href="https://pcisig.com/sites/default/files/files/PCI-SIG%20Cabling%20Webinar_FINAL.pdf" target="_blank" rel="noreferrer">PCI-SIGの転送レート・符号化・信号方式の表</a></p><table tabindex="0"><thead><tr><th>世代</th><th style="text-align:right;">1レーンの転送回数</th><th style="text-align:right;">x1の片方向</th><th style="text-align:right;">x4の片方向</th><th style="text-align:right;">x16の片方向</th></tr></thead><tbody><tr><td>Gen 3</td><td style="text-align:right;">8 GT/s</td><td style="text-align:right;">約0.98 GB/s</td><td style="text-align:right;">約3.94 GB/s</td><td style="text-align:right;">約15.75 GB/s</td></tr><tr><td>Gen 4</td><td style="text-align:right;">16 GT/s</td><td style="text-align:right;">約1.97 GB/s</td><td style="text-align:right;">約7.88 GB/s</td><td style="text-align:right;">約31.51 GB/s</td></tr><tr><td>Gen 5</td><td style="text-align:right;">32 GT/s</td><td style="text-align:right;">約3.94 GB/s</td><td style="text-align:right;">約15.75 GB/s</td><td style="text-align:right;">約63.02 GB/s</td></tr></tbody></table><p>表は符号化の分を引いた段階の帯域です。アプリのデータに加えて、PCIeではトランザクションのヘッダー、読み取り要求と応答、データリンクの制御情報なども流れます。小さいデータを細かく運ぶ場合は、同じバイト数を大きなペイロードにまとめられる場合より、ペイロード以外の占める割合が増えます。<a href="https://pcisig.com/blog/evolution-pci-express-specification-its-sixth-generation-third-decade-and-still-going-strong" target="_blank" rel="noreferrer">PCI-SIGのペイロードサイズと帯域効率の比較</a> · <a href="https://docs.kernel.org/driver-api/pci/pci.html#c.pcie_get_mps" target="_blank" rel="noreferrer">Linux PCIの最大ペイロードと最大読み取り要求</a></p><h2 id="リンクの上限と処理時間を切り分ける" tabindex="-1">リンクの上限と処理時間を切り分ける <a class="header-anchor" href="#リンクの上限と処理時間を切り分ける" aria-label="Permalink to &quot;リンクの上限と処理時間を切り分ける&quot;">​</a></h2><p>図のSSDとNICが同時にRAMへデータを書き込むと、両者は上流x4の同じ方向を使います。個々の下流リンクが速くても、上流の帯域が合計の上限になります。SSDを単独で読む場合は、経路の各リンクに加え、SSD内部の処理、要求サイズ、同時に出している要求の数、OSのキャッシュ、読み取り後の展開も時間に影響します。ゲームのロードでは、転送量と完了までの時間を段階ごとに測り、どの区間が実際に遅いかを調べます。<a href="https://docs.kernel.org/driver-api/pci/pci.html#c.pcie_bandwidth_available" target="_blank" rel="noreferrer">Linuxの経路上の帯域制約</a> · <a href="/study/tools/windows/file-io-tracing.html">WindowsのI/Oトレース</a> · <a href="/study/game/directstorage.html">DirectStorageの読み取りと展開</a></p><p>PCIeを通るデータの出発点と行き先を決めるとき、ドライバーはデバイスが使えるアドレスを用意します。<a href="/study/hardware/io/dma-and-iommu.html">DMAとIOMMU</a></p>',16)])])}const x=t(n,[["render",o]]);export{f as __pageData,x as default};
